// =============================================================================
// Project:    ProtocolX RISC-V 5-Stage Pipelined Processor
// File:       tb_riscv_subset.v
// Description: Full Project-3 instruction subset test (ADD, SUB, ADDI, LW, SW,
//              BEQ, BNE) plus a measured cycle count and CPI.
//              Program: testbench/programs/prog_subset.hex
//                (generated by testbench/programs/gen_prog_subset.py)
//              23 instructions execute dynamically (5-iteration BNE loop).
//              Expected cycles = 23 + 4 (pipeline fill) + 1 (load-use stall)
//                              + 5 taken branches x 2 flushed slots = 38.
// =============================================================================
`timescale 1ns / 1ps
`include "riscv_defines_n.vh"

module tb_riscv_subset;

    localparam integer DYN_INSTR       = 23;
    localparam integer EXPECTED_CYCLES = 38;

    reg clk   = 1'b0;
    reg rst_n = 1'b0;
    always #5 clk = ~clk;

    wire [`XLEN-1:0]           current_pc;
    wire [`XLEN-1:0]           current_instr;
    wire [`XLEN-1:0]           wb_data;
    wire [`REG_ADDR_WIDTH-1:0] wb_rd;
    wire                       wb_reg_write;

    riscv_core #(
        .IMEM_DEPTH(1024),
        .DMEM_DEPTH(1024),
        .INIT_FILE("testbench/programs/prog_subset.hex")
    ) dut (
        .clk(clk),
        .rst_n(rst_n),
        .current_pc(current_pc),
        .current_instr(current_instr),
        .wb_data_out(wb_data),
        .wb_rd_out(wb_rd),
        .wb_reg_write_out(wb_reg_write)
    );

    integer cycle_count  = 0;
    integer stall_cycles = 0;
    integer flush_events = 0;
    integer done_cycle   = -1;
    integer pass_count   = 0;
    integer fail_count   = 0;

    initial begin
        $dumpfile("simulation/waveform_subset.vcd");
        $dumpvars(0, tb_riscv_subset);
    end

    // Performance counters, sampled every cycle after reset.
    always @(posedge clk) begin
        if (rst_n) begin
            cycle_count <= cycle_count + 1;
            if (!dut.pc_write)  stall_cycles <= stall_cycles + 1;
            if (dut.if_id_flush) flush_events <= flush_events + 1;
            // x7 is written by the last instruction: program complete.
            if (wb_reg_write && wb_rd == 5'd7 && done_cycle < 0)
                done_cycle <= cycle_count + 1;
        end
    end

    task check_reg(input [4:0] r, input [`XLEN-1:0] expected, input [8*40-1:0] note);
        begin
            if (dut.u_reg_file.registers[r] === expected) begin
                pass_count = pass_count + 1;
                $display("[PASS] x%02d = %0d | %0s", r, expected, note);
            end else begin
                fail_count = fail_count + 1;
                $display("[FAIL] x%02d = %0d, expected %0d | %0s", r, dut.u_reg_file.registers[r], expected, note);
            end
        end
    endtask

    initial begin
        $display("===============================================================================");
        $display("   PROTOCOLX RISC-V INSTRUCTION SUBSET (ADD SUB ADDI LW SW BEQ BNE) & CPI TEST  ");
        $display("===============================================================================");
        #22 rst_n = 1'b1;

        wait (done_cycle > 0);
        repeat (2) @(posedge clk);
        #1;

        check_reg(5'd1, 32'd15, "BNE loop sum 5+4+3+2+1");
        check_reg(5'd2, 32'd0,  "BNE loop counter reached 0");
        check_reg(5'd3, 32'd15, "LW reads value stored by SW");
        check_reg(5'd4, 32'd30, "ADD after load-use stall");
        check_reg(5'd5, 32'd15, "SUB");
        check_reg(5'd6, 32'd0,  "skipped by taken BEQ (flushed)");
        check_reg(5'd7, 32'd1,  "BEQ target executed");

        if (dut.u_dmem.memory[0] === 32'd15) begin
            pass_count = pass_count + 1;
            $display("[PASS] mem[0] = 15 | SW wrote data memory");
        end else begin
            fail_count = fail_count + 1;
            $display("[FAIL] mem[0] = %0d, expected 15 | SW wrote data memory", dut.u_dmem.memory[0]);
        end

        if (done_cycle == EXPECTED_CYCLES) begin
            pass_count = pass_count + 1;
            $display("[PASS] completed in %0d cycles (expected %0d)", done_cycle, EXPECTED_CYCLES);
        end else begin
            fail_count = fail_count + 1;
            $display("[FAIL] completed in %0d cycles (expected %0d)", done_cycle, EXPECTED_CYCLES);
        end

        $display("-------------------------------------------------------------------------------");
        $display("PERFORMANCE (measured): instructions = %0d | cycles = %0d | stall cycles = %0d | taken-branch flushes = %0d",
                 DYN_INSTR, done_cycle, stall_cycles, flush_events);
        $display("CPI (incl. 4-cycle pipeline fill) = %0d.%02d | CPI (steady state, excl. fill) = %0d.%02d",
                 ((done_cycle * 100 + DYN_INSTR / 2) / DYN_INSTR) / 100,
                 ((done_cycle * 100 + DYN_INSTR / 2) / DYN_INSTR) % 100,
                 (((done_cycle - 4) * 100 + DYN_INSTR / 2) / DYN_INSTR) / 100,
                 (((done_cycle - 4) * 100 + DYN_INSTR / 2) / DYN_INSTR) % 100);
        $display("Subset & CPI Summary: %0d Passed, %0d Failed", pass_count, fail_count);
        $display("===============================================================================");
        $finish;
    end

    initial begin
        #10000;
        $display("[FAIL] TIMEOUT: program did not complete");
        $display("Subset & CPI Summary: 0 Passed, 1 Failed");
        $finish;
    end

endmodule
